#include <vector>

std::vector<int> primesUpTo(int n) {
    std::vector<int> res;
    if (n < 2) return res;
    std::vector<char> comp(n + 1, 0);
    for (long long p = 2; p * p <= n; ++p) {
        if (comp[p]) continue;
        for (long long q = p * p; q <= n; q += p)
            comp[q] = 1;
    }
    for (int i = 2; i <= n; ++i)
        if (!comp[i]) res.push_back(i);
    return res;
}
// time O(n log log n), space O(n)

