#include <string>
#include <vector>

std::string multiply(const std::string& a, const std::string& b) {
  if (a == "0" || b == "0") return "0";
  int m = a.size(), n = b.size();
  std::vector<int> acc(m + n, 0);          // the product has at most m + n digits
  for (int i = m - 1; i >= 0; --i)
    for (int j = n - 1; j >= 0; --j) {
      // digit i times digit j lands in positions i + j (carry) and i + j + 1
      int sum = (a[i] - '0') * (b[j] - '0') + acc[i + j + 1];
      acc[i + j + 1] = sum % 10;
      acc[i + j] += sum / 10;
    }
  std::string out;
  for (int d : acc)
    if (!(out.empty() && d == 0)) out += char('0' + d);   // skip leading zeros
  return out;
}

#include <string>

// Direct index math, O(n) time, O(1) extra memory besides the output.
// One full zigzag cycle has length L = 2*(rows-1). Row r takes the characters at
// positions k*L + r, and, for middle rows, also k*L + L - r.
std::string convert(const std::string& s, int rows) {
  if (rows == 1 || rows >= (int)s.size()) return s;
  const int L = 2 * (rows - 1), n = s.size();
  std::string out;
  out.reserve(n);
  for (int r = 0; r < rows; ++r)
    for (int k = 0; k + r < n; k += L) {
      out += s[k + r];                                   // the "down" stroke
      if (r != 0 && r != rows - 1 && k + L - r < n)
        out += s[k + L - r];                             // the "up" diagonal
    }
  return out;
}

#include <climits>

// Reverse the decimal digits of a 32-bit int; return 0 if the result overflows.
// Constraint: no 64-bit integers allowed.
int reverse(int x) {
  int r = 0;
  while (x != 0) {
    int d = x % 10;                  // C++: same sign as x (-123 % 10 == -3)
    x /= 10;
    if (r > INT_MAX / 10 || (r == INT_MAX / 10 && d > 7)) return 0;   // INT_MAX ends with 7
    if (r < INT_MIN / 10 || (r == INT_MIN / 10 && d < -8)) return 0;  // INT_MIN ends with 8
    r = r * 10 + d;
  }
  return r;
}

// Palindrome check without converting to a string, and without overflow:
// reverse only the lower half of the digits and compare it with the upper half.
bool isPalindrome(int x) {
  if (x < 0 || (x % 10 == 0 && x != 0)) return false;   // "-121" and "10" can't be palindromes
  int half = 0;
  while (x > half) {
    half = half * 10 + x % 10;
    x /= 10;
  }
  return x == half || x == half / 10;   // odd length: the middle digit sits in half
}

