def column_title(n: int) -> str:
    # Bijective base 26: digits are 1..26 (A..Z), there is no zero digit.
    out = []
    while n > 0:
        n -= 1                                # shift 1..26 to 0..25 before taking the digit
        out.append(chr(ord("A") + n % 26))
        n //= 26
    return "".join(reversed(out))


def column_number(title: str) -> int:
    n = 0
    for ch in title:
        n = n * 26 + (ord(ch) - ord("A") + 1)  # Horner's rule with digits 1..26
    return n

