def third_max(a):
    top = []               # distinct values, descending, at most 3
    for x in a:
        if x in top:
            continue
        top.append(x)
        top.sort(reverse=True)
        if len(top) > 3:
            top.pop()
    return top[2] if len(top) == 3 else top[0]

int maximumProduct(const std::vector<int>& a) {
    int max1 = INT_MIN, max2 = INT_MIN, max3 = INT_MIN;
    int min1 = INT_MAX, min2 = INT_MAX;
    for (int x : a) {
        if (x > max1) { max3 = max2; max2 = max1; max1 = x; }
        else if (x > max2) { max3 = max2; max2 = x; }
        else if (x > max3) max3 = x;
        if (x < min1) { min2 = min1; min1 = x; }
        else if (x < min2) min2 = x;
    }
    return std::max(max1 * max2 * max3, min1 * min2 * max1);
}

std::vector<std::vector<int>> minimumAbsDifference(std::vector<int> a) {
    std::sort(a.begin(), a.end());
    int best = INT_MAX;
    for (size_t i = 0; i + 1 < a.size(); i++)
        best = std::min(best, a[i + 1] - a[i]);
    std::vector<std::vector<int>> res;
    for (size_t i = 0; i + 1 < a.size(); i++)
        if (a[i + 1] - a[i] == best) res.push_back({a[i], a[i + 1]});
    return res;
}

