std::uint64_t powMod(std::uint64_t x, std::uint64_t n, std::uint64_t m) {
    using u128 = unsigned __int128;           // GCC/Clang; avoids 64x64 overflow
    std::uint64_t result = 1 % m;             // handles m == 1
    x %= m;
    while (n > 0) {
        if (n & 1) result = (u128)result * x % m;
        x = (u128)x * x % m;                  // square for the next bit
        n >>= 1;
    }
    return result;
}

