void transposeBlocked(const std::vector<float>& src, std::vector<float>& dst, int n, int B = 32) {
    dst.resize((size_t)n * n);
    for (int ii = 0; ii < n; ii += B)
        for (int jj = 0; jj < n; jj += B) {
            int iEnd = std::min(ii + B, n), jEnd = std::min(jj + B, n);   // edge tiles
            for (int i = ii; i < iEnd; ++i)
                for (int j = jj; j < jEnd; ++j)
                    dst[(size_t)j * n + i] = src[(size_t)i * n + j];
        }
}

