std::uint64_t trailingZeros(std::uint64_t n) {
    std::uint64_t zeros = 0;
    while (n > 0) {          // n/5 + n/25 + n/125 + ...
        n /= 5;              // dividing n avoids computing 5^k (which can overflow)
        zeros += n;
    }
    return zeros;
}

#include <vector>
#include <cstddef>

std::vector<float> nchwToNhwc(const std::vector<float>& in, int N, int C, int H, int W) {
    std::vector<float> out(in.size());
    std::size_t src = 0;
    for (int n = 0; n < N; ++n)
        for (int c = 0; c < C; ++c)
            for (int h = 0; h < H; ++h)
                for (int w = 0; w < W; ++w, ++src) {          // read sequentially
                    std::size_t dst = ((std::size_t(n) * H + h) * W + w) * C + c;
                    out[dst] = in[src];
                }
    return out;
}

#include <list>
#include <map>
#include <vector>

class MaxStack {
    std::list<int> st_;                                        // back = top
    std::map<int, std::vector<std::list<int>::iterator>> pos_; // value -> its nodes, oldest first
public:
    void push(int x) {
        st_.push_back(x);
        pos_[x].push_back(std::prev(st_.end()));
    }
    int pop() {
        int x = st_.back();
        auto it = pos_.find(x);
        it->second.pop_back();              // the top copy is the newest one
        if (it->second.empty()) pos_.erase(it);
        st_.pop_back();
        return x;
    }
    int top() const { return st_.back(); }
    int peekMax() const { return pos_.rbegin()->first; }
    int popMax() {
        auto it = std::prev(pos_.end());
        int x = it->first;
        st_.erase(it->second.back());       // newest copy = closest to the top
        it->second.pop_back();
        if (it->second.empty()) pos_.erase(it);
        return x;
    }
};

