int stableSortedPosition(const std::vector<int>& a, int i) {
    int pos = 0;
    for (int j = 0; j < (int)a.size(); ++j)
        if (a[j] < a[i] || (a[j] == a[i] && j < i))   // smaller, or equal and earlier
